#include <iostream>
#include <stack>
#include <string>
using namespace std;

int main() {
    int n;
    cin >> n;
    stack<int> st;
    for (int k = 0; k < n; k++) {
        string cmd;
        cin >> cmd;
        if (cmd == "push") {
            int x;
            cin >> x;
            st.push(x);
        } else if (cmd == "pop") {
            if (st.empty()) cout << "empty" << endl;
            else { cout << st.top() << endl; st.pop(); }
        } else {
            if (st.empty()) cout << "empty" << endl;
            else cout << st.top() << endl;
        }
    }
    return 0;
}
